        left = [r for r in range(h) if grid[r][0] == color]
        right = [r for r in range(h) if grid[r][w-1] == color]
        if top and bottom:
            candidates.append((len(top)+len(bottom), color, 'horizontal', top, bottom))
        if left and right:
            candidates.append((len(left)+len(right), color, 'vertical', left, right))
    if not candidates:
        return out
    _, wall, orient, a, b = max(candidates, key=lambda x: x[0])
    sides = [('top', a), ('bottom', b)] if orient == 'horizontal' else [('left', a), ('right', b)]
    markers = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != wall]
    for r,c,color in markers:
        p = c if orient == 'horizontal' else r
        matches = [(s, vals) for s,vals in sides if vals and min(vals) <= p <= max(vals)]
        if not matches:
            continue
        source, vals = matches[0]
        opposite, other = next((s,v) for s,v in sides if s != source)
        mapped = min(other) + p - min(vals)
        if orient == 'horizontal':
            dr = -1 if source == 'top' else 1
            rr = r + dr
            while 0 <= rr < h and grid[rr][c] != wall:
                out[rr][c] = color
                rr += dr
            if 0 <= mapped < w:
                start, step = (0,1) if opposite == 'top' else (h-1,-1)
                rr = start
                while 0 <= rr < h and grid[rr][mapped] != wall:
                    out[rr][mapped] = color
                    rr += step
        else:
            dc = -1 if source == 'left' else 1
            cc = c + dc
            while 0 <= cc < w and grid[r][cc] != wall:
                out[r][cc] = color
                cc += dc
            if 0 <= mapped < h:
                start, step = (0,1) if opposite == 'left' else (w-1,-1)
                cc = start
                while 0 <= cc < w and grid[mapped][cc] != wall:
                    out[mapped][cc] = color
                    cc += step
    for r,c,_ in markers:
        out[r][c] = 4
    return out
